<div class="d-flex justify-content-between align-items-center mb-3"><h4>Attendance</h4><form class="d-flex gap-2"><input type="date" name="date" class="form-control" value="<?php echo htmlspecialchars($date); ?>"><button class="btn btn-outline-secondary">Filter</button></form></div>
<?php if ($_SESSION['user_role'] === 'employee'): ?><div class="mb-3"><form method="POST" action="<?php echo BASE_URL; ?>/attendance/check-in" class="d-inline"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><button class="btn btn-success">Check in</button></form> <form method="POST" action="<?php echo BASE_URL; ?>/attendance/check-out" class="d-inline"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><button class="btn btn-outline-danger">Check out</button></form></div><?php endif; ?>
<div class="card p-3"><table class="table mb-0"><thead><tr><th>Employee</th><th>Date</th><th>In</th><th>Out</th><th>Status</th></tr></thead><tbody><?php foreach ($attendance as $row): ?><tr><td><?php echo htmlspecialchars($row['first_name'].' '.$row['last_name']); ?></td><td><?php echo htmlspecialchars($row['attendance_date']); ?></td><td><?php echo htmlspecialchars($row['check_in'] ?? '—'); ?></td><td><?php echo htmlspecialchars($row['check_out'] ?? '—'); ?></td><td><?php echo htmlspecialchars($row['status']); ?></td></tr><?php endforeach; ?></tbody></table></div>
